function groups(s){let result=[],invoices=new Map();for(let c of s.costs){if(!c.purchase){result.push({...c,grouped:false,records:[c]});continue}let group=invoices.get(c.purchase);if(!group){let p=(s.purchases||[]).find(p=>p.id===c.purchase);group={id:'invoice:'+c.purchase,purchase:c.purchase,grouped:true,records:[],supplier:p?.supplier||c.supplier,description:p?(p.kind+' '+(p.number||'sem número')):c.description,date:p?.date||c.date||'',amount:0,incurred:0,paid:0,paymentDiscount:0,paymentAddition:0,paidDate:'',due:'',project:c.project,stage:'',category:c.category};invoices.set(c.purchase,group);result.push(group)}group.records.push(c);for(let key of ['amount','incurred','paid','paymentDiscount','paymentAddition'])group[key]=Math.round((group[key]+Number(c[key]||0))*100)/100;if(c.paidDate>group.paidDate)group.paidDate=c.paidDate}for(let g of invoices.values()){let active=g.records.filter(c=>D.costBalance(c)>0);g.due=(active.length?active:g.records).map(c=>c.due).filter(Boolean).sort()[0]||'';g.projects=[...new Set(g.records.map(c=>c.project))];g.stages=[...new Set(g.records.map(c=>c.stage))]}return result}
